static bool cold_files_equal(const char *left, const char *right) {
    Span a = source_open(left);
    Span b = source_open(right);
    bool ok = a.len > 0 && b.len > 0 &&
              a.len == b.len &&
              memcmp(a.ptr, b.ptr, (size_t)a.len) == 0;
    if (a.len > 0) source_close(a);
    if (b.len > 0) source_close(b);
    return ok;
}

static void cold_restore_env_value(const char *key, const char *value) {
    if (!key || key[0] == '\0') return;
    if (value) setenv(key, value, 1);
    else unsetenv(key);
}

static char *cold_copy_env_value(const char *value) {
    if (!value) return 0;
    size_t len = strlen(value);
    char *copy = (char *)malloc(len + 1);
    if (!copy) return 0;
    memcpy(copy, value, len + 1);
    return copy;
}

static bool cold_truthy_env(const char *key) {
    if (!key || key[0] == '\0') return false;
    const char *raw = getenv(key);
    if (!raw || raw[0] == '\0') return false;
    if (strcmp(raw, "0") == 0 || strcmp(raw, "false") == 0) return false;
    return true;
}

/* RSI C1/C2 逐相相位行发射（合同 A8/W2 载具侧接线）: CHENG_PROGRESS=1 时向
   stderr 发射与烤制回执同口径的 phase= 行——相名取回执 exec_phase_* 字段尾
   (parse/codegen/direct_object_emit/total), 不另造相; 值 = 同一回执字段的
   同一分段差值。guard --phase-trace 对每行子进程 stderr 落
   "<epoch秒> TAB <进程树KiB> TAB <本行>" (runtime.py drain_phase_trace),
   即 compiler_domain.cheng cdCountPhaseRowsInto 的逐相读数来源。
   env 未开时零输出零副作用。 */
static void cold_emit_phase_line_us(const char *phase_name, uint64_t phase_us) {
    if (!cold_truthy_env("CHENG_PROGRESS")) return;
    fprintf(stderr, "phase=%s exec_phase_%s_us=%llu\n",
            phase_name, phase_name, (unsigned long long)phase_us);
    fflush(stderr);
}

static uint64_t cold_now_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) return 0;
    return (uint64_t)ts.tv_sec * 1000000ULL + (uint64_t)ts.tv_nsec / 1000ULL;
}

static void cold_print_elapsed_ms(FILE *file, const char *key, uint64_t elapsed_us) {
    fprintf(file, "%s=%llu.%03llu\n",
            key,
            (unsigned long long)(elapsed_us / 1000ULL),
            (unsigned long long)(elapsed_us % 1000ULL));
}

static bool cold_file_contains_text(const char *path, const char *needle) {
    Span haystack = source_open(path);
    int32_t n = (int32_t)strlen(needle);
    bool ok = false;
    if (haystack.len > 0 && n > 0 && haystack.len >= n) {
        for (int32_t i = 0; i <= haystack.len - n; i++) {
            if (memcmp(haystack.ptr + i, needle, (size_t)n) == 0) {
                ok = true;
                break;
            }
        }
    }
    if (haystack.len > 0) source_close(haystack);
    return ok;
}

static bool cold_file_key_equals(const char *path, const char *key, const char *value) {
    if (!path || !key || !value || key[0] == '\0') return false;
    char needle[COLD_NAME_CAP * 2];
    int n = snprintf(needle, sizeof(needle), "%s=%s\n", key, value);
    if (n <= 0 || n >= (int)sizeof(needle)) return false;
    return cold_file_contains_text(path, needle);
}

static bool cold_file_starts_with_text(const char *path, const char *prefix) {
    Span haystack = source_open(path);
    int32_t n = (int32_t)strlen(prefix);
    bool ok = haystack.len >= n && n > 0 &&
              memcmp(haystack.ptr, prefix, (size_t)n) == 0;
    if (haystack.len > 0) source_close(haystack);
    return ok;
}

static bool cold_run_shell(const char *cmd, const char *label) {
    int rc = system(cmd);
    if (rc == 0) return true;
    if (WIFEXITED(rc)) {
        fprintf(stderr, "[cheng_cold] %s failed rc=%d\n", label, WEXITSTATUS(rc));
    } else {
        fprintf(stderr, "[cheng_cold] %s failed\n", label);
    }
    return false;
}

static bool cold_shell_quote(char *out, size_t cap, const char *text);

static const char *cold_env_or_default2(const char *primary_key,
                                        const char *compat_key,
                                        const char *fallback) {
    const char *value = primary_key ? getenv(primary_key) : 0;
    if (value && value[0] != '\0') return value;
    value = compat_key ? getenv(compat_key) : 0;
    if (value && value[0] != '\0') return value;
    return fallback;
}

static const char *cold_darwin_env_flags_or_default(const char *primary_key,
                                                    const char *compat_key,
                                                    const char *fallback) {
    const char *value = primary_key ? getenv(primary_key) : 0;
    if (!value || value[0] == '\0') value = compat_key ? getenv(compat_key) : 0;
    if (!value || value[0] == '\0') return fallback;
    if (strcmp(value, "none") == 0 || strcmp(value, "NONE") == 0) return "";
    return value;
}

#define COLD_DARWIN_DIRECT_LD_PATH \
    "/Library/Developer/CommandLineTools/usr/bin/ld"
#define COLD_DARWIN_DIRECT_LTO_PATH \
    "/Library/Developer/CommandLineTools/usr/lib/libLTO.dylib"
#define COLD_DARWIN_DIRECT_RUNTIME_PATH \
    "/Library/Developer/CommandLineTools/usr/lib/clang/21/lib/darwin/libclang_rt.osx.a"
#define COLD_DARWIN_DIRECT_SDK_PATH \
    "/Library/Developer/CommandLineTools/SDKs/MacOSX.sdk"
#define COLD_DARWIN_DIRECT_SDK_SETTINGS_PATH \
    COLD_DARWIN_DIRECT_SDK_PATH "/SDKSettings.json"
#define COLD_DARWIN_DIRECT_PLATFORM_MIN "26.0.0"
#define COLD_DARWIN_DIRECT_PLATFORM_SDK "26.5"
