static const char *cold_darwin_libtool_path(void) {
    return cold_env_or_default2("CHENG_DARWIN_LIBTOOL",
                                "CHENG_CLT_LIBTOOL",
                                "/Library/Developer/CommandLineTools/usr/bin/libtool");
}

static bool cold_darwin_clt_cc_prefix(char *out, size_t cap,
                                      char *error_buf, size_t error_cap) {
    const char *cc = cold_darwin_cc_path();
    const char *sdk = cold_darwin_sysroot_path();
    const char *arch_flags = cold_darwin_arch_flags();
    struct stat sdk_st;
    if (access(cc, X_OK) != 0) {
        snprintf(error_buf, error_cap, "missing Darwin cc: %s", cc);
        return false;
    }
    if (stat(sdk, &sdk_st) != 0 || !S_ISDIR(sdk_st.st_mode)) {
        snprintf(error_buf, error_cap, "missing Darwin sysroot: %s", sdk);
        return false;
    }
    char q_cc[PATH_MAX * 2];
    char q_sdk[PATH_MAX * 2];
    if (!cold_shell_quote(q_cc, sizeof(q_cc), cc) ||
        !cold_shell_quote(q_sdk, sizeof(q_sdk), sdk)) {
        snprintf(error_buf, error_cap, "Darwin toolchain path quote failed");
        return false;
    }
    int n = snprintf(out, cap, "%s -isysroot %s %s", q_cc, q_sdk, arch_flags);
    if (n <= 0 || n >= (int)cap) {
        snprintf(error_buf, error_cap, "Darwin cc command too long");
        return false;
    }
    return true;
}

static bool cold_darwin_clt_tool(char *out, size_t cap,
                                 const char *tool_name,
                                 char *error_buf, size_t error_cap) {
    char tool_path[PATH_MAX];
    const char *configured_tool = 0;
    if (tool_name && strcmp(tool_name, "libtool") == 0) {
        configured_tool = cold_darwin_libtool_path();
    }
    if (configured_tool && configured_tool[0] != '\0') {
        int npath = snprintf(tool_path, sizeof(tool_path), "%s", configured_tool);
        if (npath <= 0 || npath >= (int)sizeof(tool_path)) {
            snprintf(error_buf, error_cap, "Darwin tool path too long");
            return false;
        }
    } else {
        int npath = snprintf(tool_path, sizeof(tool_path),
                             "/Library/Developer/CommandLineTools/usr/bin/%s",
                             tool_name);
        if (npath <= 0 || npath >= (int)sizeof(tool_path)) {
            snprintf(error_buf, error_cap, "Darwin tool path too long");
            return false;
        }
    }
    if (access(tool_path, X_OK) != 0) {
        snprintf(error_buf, error_cap, "missing Darwin tool");
        return false;
    }
    if (!cold_shell_quote(out, cap, tool_path)) {
        snprintf(error_buf, error_cap, "Darwin tool quote failed");
        return false;
    }
    return true;
}

static bool cold_run_executable_noargs_rc(const char *path, int32_t expected_rc) {
    pid_t pid = fork();
    if (pid < 0) return false;
    if (pid == 0) {
        execl(path, path, (char *)0);
        _exit(127);
    }
    int status = 0;
    if (waitpid(pid, &status, 0) < 0) return false;
    return WIFEXITED(status) && WEXITSTATUS(status) == expected_rc;
}

static bool cold_run_executable_noargs_rc_in_dir_label(const char *path,
                                                       int32_t expected_rc,
                                                       const char *cwd,
                                                       const char *label,
                                                       const char *smoke_compiler) {
    pid_t pid = fork();
    if (pid < 0) return false;
    if (pid == 0) {
        if (cwd && cwd[0] != '\0' && chdir(cwd) != 0) _exit(126);
        if (label && label[0] != '\0') setenv("CHENG_SMOKE_LABEL", label, 1);
        if (smoke_compiler && smoke_compiler[0] != '\0') {
            setenv("CHENG_SMOKE_COMPILER", smoke_compiler, 1);
        }
        execl(path, path, (char *)0);
        _exit(127);
    }
    int status = 0;
    if (waitpid(pid, &status, 0) < 0) return false;
    return WIFEXITED(status) && WEXITSTATUS(status) == expected_rc;
}

static bool cold_run_executable_one_arg_expect_stdout_all(const char *path,
                                                          const char *arg,
                                                          int32_t expected_rc,
                                                          const char **expected_stdout_markers,
                                                          int32_t expected_stdout_marker_count) {
    int pipefd[2];
    if (pipe(pipefd) != 0) return false;
    pid_t pid = fork();
    if (pid < 0) {
        close(pipefd[0]);
        close(pipefd[1]);
        return false;
    }
    if (pid == 0) {
        close(pipefd[0]);
        dup2(pipefd[1], STDOUT_FILENO);
        close(pipefd[1]);
        execl(path, path, arg, (char *)0);
        _exit(127);
    }
    close(pipefd[1]);
    char out[8192];
    int32_t used = 0;
    for (;;) {
        ssize_t n = read(pipefd[0], out + used, (size_t)(sizeof(out) - 1 - (size_t)used));
        if (n <= 0) break;
        used += (int32_t)n;
        if (used >= (int32_t)sizeof(out) - 1) break;
    }
    out[used] = '\0';
    close(pipefd[0]);
    int status = 0;
    if (waitpid(pid, &status, 0) < 0) return false;
    if (!WIFEXITED(status) || WEXITSTATUS(status) != expected_rc) return false;
    for (int32_t i = 0; i < expected_stdout_marker_count; i++) {
        if (!expected_stdout_markers[i] || strstr(out, expected_stdout_markers[i]) == 0) {
            return false;
        }
    }
    return true;
}

static bool cold_run_executable_one_arg_expect_stdout(const char *path,
                                                      const char *arg,
                                                      int32_t expected_rc,
                                                      const char *expected_stdout_marker) {
    const char *markers[1] = { expected_stdout_marker };
    return cold_run_executable_one_arg_expect_stdout_all(path, arg, expected_rc, markers, 1);
}

static bool cold_shell_quote(char *out, size_t cap, const char *text) {
    size_t used = 0;
    if (cap < 3) return false;
    out[used++] = '\'';
    for (size_t i = 0; text[i] != '\0'; i++) {
        if (text[i] == '\'') {
            if (used + 4 >= cap) return false;
            out[used++] = '\'';
            out[used++] = '\\';
            out[used++] = '\'';
            out[used++] = '\'';
        } else {
            if (used + 1 >= cap) return false;
            out[used++] = text[i];
        }
    }
    if (used + 1 >= cap) return false;
    out[used++] = '\'';
    out[used] = '\0';
    return true;
}

