static const char *cold_bootstrap_self_image_executable_format(
        const uint8_t *data,
        size_t length) {
    if (!data) return 0;
    if (length >= 16u &&
        data[0] == 0xcfu && data[1] == 0xfau &&
        data[2] == 0xedu && data[3] == 0xfeu &&
        data[4] == 0x0cu && data[5] == 0x00u &&
        data[6] == 0x00u && data[7] == 0x01u &&
        data[12] == 0x02u && data[13] == 0x00u &&
        data[14] == 0x00u && data[15] == 0x00u) {
        return "macho64-arm64-darwin";
    }
    if (length >= 64u &&
        data[0] == 0x7fu && data[1] == 'E' &&
        data[2] == 'L' && data[3] == 'F' &&
        data[4] == ELFCLASS64 &&
        data[5] == ELFDATA2LSB &&
        data[6] == EV_CURRENT &&
        (data[16] == ET_EXEC || data[16] == ET_DYN) &&
        data[17] == 0u &&
        data[18] == EM_X86_64 && data[19] == 0u &&
        data[20] == EV_CURRENT && data[21] == 0u &&
        data[22] == 0u && data[23] == 0u) {
        return "elf64-x86_64-linux";
    }
    return 0;
}

