typedef struct ColdBodyOpSchema {
    int16_t kind;
    bool reads_a_slot;
    bool reads_b_slot;
    bool reads_c_slot;
    bool reads_dst_slot;
    bool writes_dst_slot;
    uint8_t mutation_referent_mask;
    bool has_side_effect;
    uint8_t target_support_mask;
} ColdBodyOpSchema;

enum {
    COLD_BODY_ACCESS_NONE = 0,
    COLD_BODY_ACCESS_DST = 1 << 0,
    COLD_BODY_ACCESS_A = 1 << 1,
    COLD_BODY_ACCESS_B = 1 << 2,
    COLD_BODY_ACCESS_C = 1 << 3,
};

enum {
    COLD_BODY_TARGET_A64 = 1 << 0,
    COLD_BODY_TARGET_X64 = 1 << 1,
    COLD_BODY_TARGET_RV64 = 1 << 2,
    COLD_BODY_TARGET_WASM = 1 << 3,
    COLD_BODY_TARGET_NATIVE = COLD_BODY_TARGET_A64 |
                              COLD_BODY_TARGET_X64 |
                              COLD_BODY_TARGET_RV64,
    COLD_BODY_TARGET_A64_X64 = COLD_BODY_TARGET_A64 |
                               COLD_BODY_TARGET_X64,
    COLD_BODY_TARGET_A64_X64_WASM = COLD_BODY_TARGET_A64 |
                                    COLD_BODY_TARGET_X64 |
                                    COLD_BODY_TARGET_WASM,
    COLD_BODY_TARGET_ALL = COLD_BODY_TARGET_NATIVE |
                           COLD_BODY_TARGET_WASM,
};

/* Target capability is the sixth fact on every one of the 172 rows.  There
   is no default-capability expression: appending an opcode without choosing
   an explicit backend set cannot compile this table. */
#define COLD_BODY_OP_SCHEMA(op_kind, read_mask, write_dst, mutation_mask, \
                            side_effect, target_support) \
    { (int16_t)(op_kind), \
      ((read_mask) & COLD_BODY_ACCESS_A) != 0, \
      ((read_mask) & COLD_BODY_ACCESS_B) != 0, \
      ((read_mask) & COLD_BODY_ACCESS_C) != 0, \
      ((read_mask) & COLD_BODY_ACCESS_DST) != 0, \
      (write_dst), (uint8_t)(mutation_mask), (side_effect), \
      (uint8_t)(target_support) }

