/* Sparse prefilter for the exact consumer classifier.  A BodyIR op can name
   a definition only through its immutable source column, a composite CSR
   row, or the second input of an exact CFG merge.  Dataflow used to call the
   much larger structural classifier for every op in every visited block;
   rejecting non-candidates here preserves the classifier's domain while
   making the walk proportional to actual definition edges. */
/* A frozen borrowed call var-out NOP records its superseded definition in
   origin_id and keeps source_id = -1 by design -- the consume predicate's
   fourth true-lane. Every candidate enumeration (the shared namer below,
   the parse-time inverted index, the frozen first-consume table, and the
   freeze-audit consumer summary) must cover this channel or consumers
   undercount against the authority predicate. Returns the named definition
   row, or -1 when the op is not that marker shape. */
static inline int32_t cold_frozen_var_out_nop_origin_definition(
        const BodyIR *body, int32_t consumer) {
    if (!body || !body->exact_frozen ||
        consumer < 0 || consumer >= body->op_count ||
        body->op_kind[consumer] != BODY_OP_NOP ||
        body->op_value_def_place_kind[consumer] !=
            COLD_EXPR_PLACE_MEMORY_VERSION ||
        body->op_a[consumer] < 0 ||
        body->op_a[consumer] >= body->op_count ||
        body->op_source_value_def_op_id[consumer] != -1) {
        return -1;
    }
    int32_t pinned_kind = body->op_kind[body->op_a[consumer]];
    if (pinned_kind != BODY_OP_CALL_I32 &&
        pinned_kind != BODY_OP_CALL_COMPOSITE) {
        return -1;
    }
    int32_t origin = body->op_value_def_origin_id[consumer];
    return origin >= 0 && origin < body->op_count ? origin : -1;
}

static inline bool cold_op_names_definition_candidate(
        const BodyIR *body, int32_t definition,
        int32_t consumer) {
    if (!body || definition < 0 ||
        definition >= body->op_count || consumer < 0 ||
        consumer >= body->op_count) {
        return false;
    }
    if (body->op_source_value_def_op_id[consumer] == definition)
        return true;
    if (cold_frozen_var_out_nop_origin_definition(body, consumer) ==
        definition) {
        return true;
    }
    int32_t kind = body->op_kind[consumer];
    if (kind == BODY_OP_CALL_COMPOSITE ||
        kind == BODY_OP_MAKE_COMPOSITE ||
        kind == BODY_OP_MAKE_SEQ_OPAQUE) {
        int32_t start = kind == BODY_OP_MAKE_SEQ_OPAQUE
            ? body->op_a[consumer] : body->op_b[consumer];
        int32_t count = body->op_c[consumer];
        if (start < 0 || count < 0 ||
            start > body->call_arg_count ||
            count > body->call_arg_count - start) {
            return false;
        }
        for (int32_t index = 0; index < count; index++) {
            if (body->call_arg_value_def_op_id[start + index] ==
                    definition) {
                return true;
            }
        }
    }
    return body->op_value_def_place_kind[consumer] ==
               COLD_EXPR_PLACE_CFG_MERGE &&
           body->op_b[consumer] == definition;
}

