        x64_movsxd_r64_r32(x, 0, 2);                             /* rax = len (sign-extend) */
        x64_add_r64_r64(x, 0, 1);                                /* rax = ptr + len */
        x64_mov_r64_r64(x, 9, 0);                                /* r9 = right ptr = ptr+len */
        /* Left scan: skip leading whitespace (char <= ' ') */
        int32_t ls_loop = x->len;
        x64_cmp_r64_r64(x, 8, 9);                                /* flags = r9 - r8 */
        int32_t ls_exit = x->len; x64_jcc_rel8(x, CC_BE, 0);     /* if r9 <= r8 (r8>=r9), exit */
        x64_movzb_r32_mr8(x, 0, 8);                              /* eax = byte at [r8] */
        x64_cmp_r32_imm8(x, 0, ' ');
        int32_t ls_nws = x->len; x64_jcc_rel8(x, CC_A, 0);       /* if byte > ' ', not whitespace */
        x64_emit1(x, 0x49); x64_emit1(x, 0xFF); x64_emit1(x, 0xC0); /* inc r8 */
        x64_jmp_rel8(x, (int8_t)(ls_loop - (x->len + 2)));
