        x->buf[ls_nws + 1] = (uint8_t)(ls_exit_label - (ls_nws + 2));
        /* Right scan: keep r9 end-exclusive; only move it left for whitespace. */
        int32_t rs_loop = x->len;
        x64_cmp_r64_r64(x, 8, 9);                                /* flags = r9 - r8 */
        int32_t rs_exit = x->len; x64_jcc_rel8(x, CC_BE, 0);     /* if r8 >= r9, done */
        x64_mov_r64_r64(x, 10, 9);                               /* r10 = r9 */
        x64_emit1(x, 0x49); x64_emit1(x, 0xFF); x64_emit1(x, 0xCA); /* dec r10 */
        x64_movzb_r32_mr8(x, 0, 10);                             /* eax = byte at [r10] */
        x64_cmp_r32_imm8(x, 0, ' ');
        int32_t rs_nws = x->len; x64_jcc_rel8(x, CC_A, 0);       /* if byte > ' ', not whitespace */
        x64_mov_r64_r64(x, 9, 10);                               /* r9 = r10 */
        x64_jmp_rel8(x, (int8_t)(rs_loop - (x->len + 2)));
        int32_t rs_exit_label = x->len;
        x->buf[rs_exit + 1] = (uint8_t)(rs_exit_label - (rs_exit + 2));
        x->buf[rs_nws + 1] = (uint8_t)(rs_exit_label - (rs_nws + 2));
