static int output_direct_macho(const char *path, Code *code) {
    return macho_write_exec(path, code->words, code->count,
                            code->global_data,
                            code->global_data_size,
                            code->global_offsets, code->global_count,
                            code->global_patch_pos,
                            code->global_patch_idx,
                            code->global_patch_count) ? 0 : 1;
}

