static bool cold_runtime_provider_linux_core_preferred_root(const char *symbol) {
    /* driver_c_new_string / driver_c_new_string_copy_n must NOT prefer the
       Linux core provider: its cheng_runtime_malloc slab (BDMC block headers)
       never enters the ORC allocation registry, while the release side always
       comes from the program-support provider's registry-checked
       cheng_mem_release.  Routing the string constructors to the slab made
       every owned string it produced die at scope exit with
       registry_miss/wrong_object_or_owner (lazy smoke Linux run, gdb-proven:
       data=payload of a BDMC slab block, flags=owned, registry len had no
       such payload).  The program-support provider's copies allocate through
       cheng_malloc_locked, which inserts the payload into the same registry
       the release path checks — the exact pairing Darwin already uses
       (prefer_linux_core is false there, so program_support wins). */
    return strcmp(symbol, "cheng_epoch_time_seconds") == 0;
}

static bool cold_export_symbol_push(const char **exports, int32_t *count,
                                    int32_t cap, const char *symbol) {
    if (!exports || !count || !symbol || symbol[0] == '\0') return false;
    for (int32_t i = 0; i < *count; i++) {
        if (strcmp(exports[i], symbol) == 0) return true;
    }
    if (*count >= cap) return false;
    exports[(*count)++] = symbol;
    return true;
}

static bool cold_roots_csv_append(char *roots_csv, size_t cap, const char *symbol) {
    if (!roots_csv || cap == 0 || !symbol || symbol[0] == '\0') return false;
    size_t used = strlen(roots_csv);
    size_t sym_len = strlen(symbol);
    size_t need = sym_len + (used ? 1u : 0u) + 1u;
    if (used + need >= cap) return false;
    if (used) strcat(roots_csv, ",");
    strcat(roots_csv, symbol);
    return true;
}

static bool cold_roots_csv_contains(const char *roots_csv, const char *symbol) {
    if (!roots_csv || !symbol || symbol[0] == '\0') return false;
    size_t symbol_len = strlen(symbol);
    const char *p = roots_csv;
    while (*p) {
        const char *start = p;
        while (*p && *p != ',') p++;
        if ((size_t)(p - start) == symbol_len &&
            memcmp(start, symbol, symbol_len) == 0) {
            return true;
        }
        if (*p == ',') p++;
    }
    return false;
}

static bool cold_roots_csv_append_unique(char *roots_csv, size_t cap, const char *symbol) {
    if (cold_roots_csv_contains(roots_csv, symbol)) return true;
    return cold_roots_csv_append(roots_csv, cap, symbol);
}

static bool cold_symbol_list_contains_root(const char **symbols, int32_t count,
                                           bool strip_leading_underscore,
                                           const char *root) {
    if (!symbols || !root || root[0] == '\0') return false;
    for (int32_t i = 0; i < count; i++) {
        const char *sym = symbols[i];
        if (!sym) continue;
        if (strip_leading_underscore && root[0] != '_' && sym[0] == '_') sym++;
        if (strcmp(sym, root) == 0) return true;
    }
    return false;
}

/* Hosted system-link (provider_link_mode=system) must not GLOBAL-export
   nolibc stubs under libc names. Those names belong to glibc; this object
   is only consumed on the --link-providers path. Linkerless images never
   load it. Keep Cheng-owned names only. */
static bool cold_linux_syscall_provider_cheng_owned_symbol(const char *name) {
    if (!name || name[0] == '\0') return false;
    if (strncmp(name, "__cheng_", 8) == 0) return true;
    if (strncmp(name, "cheng_", 6) == 0) return true;
    if (strcmp(name, "ptr_add") == 0) return true;
    if (strcmp(name, "libc_accept") == 0) return true;
    if (strcmp(name, "spawnvp") == 0) return true;
    if (strcmp(name, "sysctlbyname") == 0) return true;
    if (strcmp(name, "proc_pidinfo") == 0) return true;
    if (strcmp(name, "proc_listpids") == 0) return true;
    return false;
}

