    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_cmp_imm_x(R1, 1));
    int32_t bad_size = code->count;
    code_emit(code, a64_bcond(0, COND_LT));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_cmp_imm_x(R2, 1));
    int32_t bad_count = code->count;
    code_emit(code, a64_bcond(0, COND_LT));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_orr_reg_x(R12, 31, R1));       /* item size */
    code_emit(code, a64_mul_reg_x(R9, R1, R2));        /* bytes */
    code_emit(code, a64_orr_reg_x(R10, 31, R0));       /* buffer */
    code_emit(code, a64_ldr_imm(R11, R3, 0, true));    /* fd */
    code_emit(code, a64_orr_reg_x(R0, 31, R11));
    code_emit(code, a64_orr_reg_x(R1, 31, R10));
    code_emit(code, a64_orr_reg_x(R2, 31, R9));
    code_emit(code, a64_movz_x(8, 64, 0));             /* write */
    code_emit(code, a64_svc(0));
    code_emit(code, a64_cmp_imm_x(R0, 0));
    int32_t write_positive = code->count;
    code_emit(code, a64_bcond(0, COND_GT));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    int32_t ret_zero = code->count;
    a64_patch_bcond(code, null_buf, ret_zero);
    a64_patch_bcond(code, null_stream, ret_zero);
    a64_patch_bcond(code, bad_size, ret_zero);
    a64_patch_bcond(code, bad_count, ret_zero);
    code_emit(code, a64_movz_x(R0, 0, 0));
    code_emit(code, a64_ret());
    a64_patch_bcond(code, write_positive, code->count);
    code_emit(code, a64_udiv_reg_x(R0, R0, R12));      /* bytes / item size */
