static void cold_emit_linux_aarch64_fclose_provider(Code *code) {
    /* fclose(x0 = stream) -> close(2) result; unmaps the handle payload. */
    code_emit(code, a64_cmp_imm_x(R0, 0));
    int32_t nonnull = code->count;
    code_emit(code, a64_bcond(0, COND_NE));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_movz_x(R0, 0, 0));
    code_emit(code, a64_ret());
    a64_patch_bcond(code, nonnull, code->count);
    code_emit(code, a64_orr_reg_x(R12, 31, R0));       /* stream */
    code_emit(code, a64_ldr_imm(R0, R12, 0, true));    /* fd */
    code_emit(code, a64_movz_x(8, 57, 0));             /* close */
    code_emit(code, a64_svc(0));
    code_emit(code, a64_orr_reg_x(R11, 31, R0));       /* close result */
    code_emit(code, a64_sub_imm(R9, R12, 16, true));   /* mapping base */
    code_emit(code, a64_ldr_imm(R1, R9, 0, true));     /* mapping bytes */
    code_emit(code, a64_orr_reg_x(R0, 31, R9));
    code_emit(code, a64_movz_x(8, 215, 0));            /* munmap */
    code_emit(code, a64_svc(0));
    code_emit(code, a64_orr_reg_x(R0, 31, R11));
    code_emit(code, a64_ret());
}

