static void cold_emit_linux_aarch64_fgetc_provider(Code *code) {
    /* fgetc(x0 = stream) -> byte or -1 */
    code_emit(code, a64_cmp_imm_x(R0, 0));
    int32_t nonnull = code->count;
    code_emit(code, a64_bcond(0, COND_NE));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_movn(R0, 0, 0));               /* -1 */
    code_emit(code, a64_ret());
    a64_patch_bcond(code, nonnull, code->count);
    code_emit(code, a64_sub_imm(SP, SP, 16, true));
    code_emit(code, a64_ldr_imm(R0, R0, 0, true));     /* fd */
    code_emit(code, a64_add_imm(R1, SP, 0, true));
    code_emit(code, a64_movz_x(R2, 1, 0));
    code_emit(code, a64_movz_x(8, 63, 0));             /* read */
    code_emit(code, a64_svc(0));
    code_emit(code, a64_cmp_imm_x(R0, 1));
    int32_t got_one = code->count;
    code_emit(code, a64_bcond(0, COND_EQ));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_movn(R0, 0, 0));
    code_emit(code, a64_add_imm(SP, SP, 16, true));
    code_emit(code, a64_ret());
    a64_patch_bcond(code, got_one, code->count);
    code_emit(code, a64_ldrb_imm(R0, SP, 0));
    code_emit(code, a64_add_imm(SP, SP, 16, true));
    code_emit(code, a64_ret());
}

static void cold_emit_linux_aarch64_fgets_provider(Code *code) {
    /* fgets(x0 = buf, x1 = size, x2 = stream) -> buf or 0; byte-at-a-time
       reads until size-1 chars, newline, or EOF (twin of the x86_64 loop). */
    code_emit(code, a64_cmp_imm_x(R0, 0));
    int32_t null_buf = code->count;
    code_emit(code, a64_bcond(0, COND_EQ));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_cmp_imm_x(R2, 0));
    int32_t null_stream = code->count;
    code_emit(code, a64_bcond(0, COND_EQ));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_orr_reg_x(R12, 31, R0));       /* buffer */
    code_emit(code, a64_orr_reg_x(13, 31, R1));        /* size */
    code_emit(code, a64_orr_reg_x(14, 31, R2));        /* stream */
    code_emit(code, a64_cmp_imm_x(13, 1));
    int32_t bad_size = code->count;
    code_emit(code, a64_bcond(0, COND_LT));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_cmp_imm_x(13, 1));
    int32_t multi = code->count;
    code_emit(code, a64_bcond(0, COND_GT));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_strb_imm(31, R12, 0));         /* size == 1: buf[0] = 0 */
    code_emit(code, a64_orr_reg_x(R0, 31, R12));
    code_emit(code, a64_ret());
    a64_patch_bcond(code, multi, code->count);
    code_emit(code, a64_sub_imm(13, 13, 1, true));     /* max chars = size - 1 */
    code_emit(code, a64_movz_x(15, 0, 0));             /* count */
    int32_t loop = code->count;
    code_emit(code, a64_cmp_reg_x(15, 13));            /* count - max */
    int32_t done_full = code->count;
    code_emit(code, a64_bcond(0, COND_GE));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_add_reg_x(R9, R12, 15));       /* write slot */
    code_emit(code, a64_ldr_imm(R0, 14, 0, true));     /* fd */
    code_emit(code, a64_orr_reg_x(R1, 31, R9));
    code_emit(code, a64_movz_x(R2, 1, 0));
    code_emit(code, a64_movz_x(8, 63, 0));             /* read */
    code_emit(code, a64_svc(0));
    code_emit(code, a64_cmp_imm_x(R0, 1));
    int32_t got_one = code->count;
    code_emit(code, a64_bcond(0, COND_EQ));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_cmp_imm_x(15, 0));
    int32_t done_partial = code->count;
    code_emit(code, a64_bcond(0, COND_NE));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    int32_t eof_b = code->count;
    code_emit(code, a64_b(0));                         /* count==0 EOF -> 0 */
    a64_patch_bcond(code, got_one, code->count);
    code_emit(code, a64_ldrb_reg(R11, R12, 15));       /* just-read char */
    code_emit(code, a64_add_imm(15, 15, 1, true));
    code_emit(code, a64_cmp_imm(R11, '\n'));
    int32_t done_nl = code->count;
    code_emit(code, a64_bcond(0, COND_EQ));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_b(loop - code->count));
    int32_t done = code->count;
    a64_patch_bcond(code, done_full, done);
    a64_patch_bcond(code, done_partial, done);
    a64_patch_bcond(code, done_nl, done);
    code_emit(code, a64_add_reg_x(R9, R12, 15));
    code_emit(code, a64_strb_imm(31, R9, 0));          /* NUL */
    code_emit(code, a64_orr_reg_x(R0, 31, R12));
    code_emit(code, a64_ret());
    int32_t ret_zero = code->count;
    a64_patch_bcond(code, null_buf, ret_zero);
    a64_patch_bcond(code, null_stream, ret_zero);
    a64_patch_bcond(code, bad_size, ret_zero);
    a64_patch_b(code, eof_b, ret_zero);
    code_emit(code, a64_movz_x(R0, 0, 0));
    code_emit(code, a64_ret());
}

static void cold_emit_linux_aarch64_errno_location_provider(Code *code) {
    /* Stable per-process errno cell at fixed page-aligned address
       0x4000000000 (below both the x86_64 and the 39-bit aarch64 mmap
       bases, far above every static-exe segment).  MAP_FIXED_NOREPLACE
       maps one page on the first call and fails EEXIST on later calls,
       leaving the SAME cell in place, so libc errno writes persist for
       cheng_native_errno_code_bridge and a foreign mapping can never be
       clobbered.  The old per-call fresh cell made errno always 0 on
       system-linked exes. */
    /* hw=2: 0x4000 << 32 = 0x4000000000. hw=1 was 0x40000000 and SIGSEGV. */
    code_emit(code, a64_movz_x(R11, 0x4000, 2));
    code_emit(code, a64_orr_reg_x(R0, 31, R11));      /* addr = cell */
    code_emit(code, a64_movz_x(R1, 4096, 0));         /* len = one page */
    code_emit(code, a64_movz_x(R2, 3, 0));            /* PROT_READ|PROT_WRITE */
    code_emit(code, a64_movz_x(R3, 0x22, 0));         /* MAP_PRIVATE|MAP_ANON */
    /* hw=1: 0x10 << 16 = MAP_FIXED_NOREPLACE. hw=16 corrupted the opcode. */
    code_emit(code, a64_movk_x(R3, 0x10, 1));
    code_emit(code, a64_movn(R4, 0, 0));              /* fd = -1 */
    code_emit(code, a64_movz_x(R5, 0, 0));            /* offset = 0 */
    code_emit(code, a64_movz_x(8, 222, 0));           /* mmap */
    code_emit(code, a64_svc(0));
    code_emit(code, a64_orr_reg_x(R0, 31, R11));      /* return the cell */
    code_emit(code, a64_ret());
}

