    x64_push_r64(x, 12);       /* r12 = out */
    x64_push_r64(x, 13);       /* r13 = fn */
    x64_push_r64(x, 14);       /* r14 = arg */
    x64_push_r64(x, 15);       /* r15 = stack base */
    x64_mov_r64_r64(x, 12, 7);     /* r12 = out (rdi) */
    x64_mov_r64_r64(x, 13, 2);     /* r13 = fn (rdx) */
    x64_mov_r64_r64(x, 14, 1);     /* r14 = arg (rcx) */

