    x64_mov_r64_r64(x, 15, 0);         /* r15 = stack base */

    /* mmap(NULL, 4096, PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANONYMOUS, -1, 0) */
    x64_xor_r64_r64(x, 7, 7);
    x64_mov_r32_imm32(x, 6, 4096);
    x64_mov_r32_imm32(x, 2, 3);
    x64_mov_r32_imm32(x, 10, 0x22);
    x64_mov_r64_imm64(x, 8, (uint64_t)-1);
    x64_xor_r64_r64(x, 9, 9);
