        wasm_op_local_get(wasm, (uint32_t)scr3);
        wasm_op_i32_const(wasm, 1);
        wasm_emit1(wasm, WASM_OP_I32_ADD);
        wasm_op_local_set(wasm, (uint32_t)scr3);
