        wasm_op_i32_const(wasm, 8);
        wasm_emit1(wasm, WASM_OP_I32_ADD);
        wasm_op_local_set(wasm, (uint32_t)SCR_TMP_PA);
        wasm_op_local_get(wasm, (uint32_t)la);
        wasm_op_i32_const(wasm, 8);
        wasm_emit1(wasm, WASM_OP_I32_ADD);
        wasm_op_local_set(wasm, (uint32_t)SCR_I_PA);
