        wasm_op_local_get(wasm, (uint32_t)SCR_LEN_PP);
        wasm_op_i32_const(wasm, 2);
        wasm_emit1(wasm, WASM_OP_I32_SUB);
        wasm_op_local_set(wasm, (uint32_t)SCR_I_PP);
        wasm_op_i32_const(wasm, -1);
        wasm_op_local_set(wasm, (uint32_t)SCR_FOUND_PP);
