        wasm_emit1(wasm, WASM_OP_IF);
        wasm_emit1(wasm, WASM_BLOCK_TYPE_EMPTY);
        wasm_op_local_get(wasm, (uint32_t)SCR_I_PP);
        wasm_op_local_set(wasm, (uint32_t)SCR_FOUND_PP);
        wasm_emit1(wasm, WASM_OP_BR);
        wasm_emit_leb128_u(wasm, 2); /* break out of block */
        wasm_emit1(wasm, WASM_OP_END);
