        /* Initialize ld = 0 (no match) */
        wasm_op_i32_const(wasm, 0);
        wasm_op_local_set(wasm, (uint32_t)ld);
        /* i = 0 */
        wasm_op_i32_const(wasm, 0);
        wasm_op_local_set(wasm, SCR_I_TC);
