        wasm_op_i32_const(wasm, 0);
        wasm_op_local_set(wasm, SCR_J_TC);
        /* block @inner_break (br target when full match found) */
        wasm_emit1(wasm, WASM_OP_BLOCK);
        wasm_emit1(wasm, WASM_BLOCK_TYPE_EMPTY);
        /* loop @inner */
        wasm_emit1(wasm, WASM_OP_LOOP);
        wasm_emit1(wasm, WASM_BLOCK_TYPE_EMPTY);
