        wasm_op_local_get(wasm, SCR_J_TC);
        wasm_op_local_get(wasm, SCR_LB_TC);
        wasm_emit1(wasm, WASM_OP_I32_GE_S);
        wasm_emit1(wasm, WASM_OP_BR_IF);
        wasm_emit_leb128_u(wasm, 1);
