static bool cold_host_can_execute_target(Span target) {
    bool target_darwin = cold_span_contains_cstr(target, "apple-darwin");
    bool target_linux = cold_span_contains_cstr(target, "linux-gnu");
    bool target_windows = cold_span_contains_cstr(target, "pc-windows-msvc");
    bool target_arm64 = cold_span_contains_cstr(target, "arm64") ||
                        cold_span_contains_cstr(target, "aarch64");
    bool target_x86_64 = cold_span_contains_cstr(target, "x86_64");
#if defined(__APPLE__)
    bool host_darwin = true;
#else
    bool host_darwin = false;
#endif
#if defined(__linux__)
    bool host_linux = true;
#else
    bool host_linux = false;
#endif
#if defined(_WIN32) || defined(__CYGWIN__) || defined(__MSYS__)
    bool host_windows = true;
#else
    bool host_windows = false;
#endif
#if defined(__aarch64__) || defined(_M_ARM64)
    bool host_arm64 = true;
#else
    bool host_arm64 = false;
#endif
#if defined(__x86_64__) || defined(_M_X64)
    bool host_x86_64 = true;
#else
    bool host_x86_64 = false;
#endif
    if (target_darwin && !host_darwin) return false;
    if (target_linux && !host_linux) return false;
    if (target_windows && !host_windows) return false;
    if (target_arm64 && !host_arm64) return false;
    if (target_x86_64 && !host_x86_64) return false;
    return target_darwin || target_linux || target_windows;
}

static bool cold_host_smoke_skip_cross_host_runtime(const char *name,
                                                    const char *target,
                                                    const char *path) {
    if (cold_host_can_execute_target(cold_cstr_span(target))) return false;
    printf("  SKIP %s runtime=cross_host_target_not_executable target=%s path=%s\n",
           name, target, path);
    return true;
}

static int cold_run_host_smoke_egraph_contract(int argc, char **argv, const char *root) {
    (void)argc;
    char out_dir[PATH_MAX];
    char source_path[PATH_MAX];
    char out_path[PATH_MAX];
    char report_path[PATH_MAX];
    char noalias_source_path[PATH_MAX];
    char noalias_out_path[PATH_MAX];
    char noalias_report_path[PATH_MAX];
    cold_join_path(out_dir, sizeof(out_dir), root, "artifacts/hostrun/cold_builtin");
    if (!cold_mkdir_p(out_dir)) {
        fprintf(stderr, "[cheng_cold] run-host-smokes: failed to create %s\n", out_dir);
        return 1;
    }
    cold_join_path(source_path, sizeof(source_path), root, "src/tests/compiler_csg_egraph_active_contract_smoke.cheng");
    cold_join_path(out_path, sizeof(out_path), out_dir, "compiler_csg_egraph_active_contract_smoke");
    cold_format_exact_or_die(
        report_path, sizeof(report_path),
        "egraph smoke report path too long",
        "%s.report.txt", out_path);
    unlink(out_path);
    unlink(report_path);
    if (!cold_file_exists_nonempty(source_path)) {
        fprintf(stderr, "[cheng_cold] run-host-smokes: missing source %s\n", source_path);
        return 1;
    }
    char root_arg[PATH_MAX + 16];
    char in_arg[PATH_MAX + 16];
    char out_arg[PATH_MAX + 16];
    char report_arg[PATH_MAX + 32];
    snprintf(root_arg, sizeof(root_arg), "--root:%s", root);
    snprintf(in_arg, sizeof(in_arg), "--in:%s", source_path);
    snprintf(out_arg, sizeof(out_arg), "--out:%s", out_path);
    snprintf(report_arg, sizeof(report_arg), "--report-out:%s", report_path);
    char *compile_argv[] = {
        argv[0],
        "system-link-exec",
        root_arg,
        in_arg,
        "--emit:exe",
        "--target:arm64-apple-darwin",
        out_arg,
        report_arg,
    };
    int rc = cold_cmd_system_link_exec(8, compile_argv);
    if (rc != 0) return rc;
    if (!cold_file_contains_text(report_path, "direct_macho=1\n") ||
        !cold_file_contains_text(report_path, "system_link=0\n") ||
        !cold_file_contains_text(report_path, "linkerless_image=1\n")) {
        fprintf(stderr, "[cheng_cold] run-host-smokes: egraph contract report mismatch: %s\n", report_path);
        return 1;
    }

    cold_join_path(noalias_source_path, sizeof(noalias_source_path), root, "src/tests/cold_noalias_egraph_contract_smoke.cheng");
    cold_join_path(noalias_out_path, sizeof(noalias_out_path), out_dir, "cold_noalias_egraph_contract_smoke");
    cold_format_exact_or_die(
        noalias_report_path, sizeof(noalias_report_path),
        "noalias smoke report path too long",
        "%s.report.txt", noalias_out_path);
    unlink(noalias_out_path);
    unlink(noalias_report_path);
    if (!cold_file_exists_nonempty(noalias_source_path)) {
        fprintf(stderr, "[cheng_cold] run-host-smokes: missing source %s\n", noalias_source_path);
        return 1;
    }
    snprintf(in_arg, sizeof(in_arg), "--in:%s", noalias_source_path);
    snprintf(out_arg, sizeof(out_arg), "--out:%s", noalias_out_path);
    snprintf(report_arg, sizeof(report_arg), "--report-out:%s", noalias_report_path);
    char *noalias_compile_argv[] = {
        argv[0],
        "system-link-exec",
        root_arg,
        in_arg,
        "--emit:exe",
        "--target:arm64-apple-darwin",
        out_arg,
        report_arg,
    };
    rc = cold_cmd_system_link_exec(8, noalias_compile_argv);
    if (rc != 0) return rc;
    if (!cold_file_contains_text(noalias_report_path, "direct_macho=1\n") ||
        !cold_file_contains_text(noalias_report_path, "no_alias_marked_slots=") ||
        cold_file_contains_text(noalias_report_path, "no_alias_marked_slots=0\n") ||
        !cold_file_contains_text(noalias_report_path, "no_alias_rejected_slots=") ||
        cold_file_contains_text(noalias_report_path, "no_alias_rejected_slots=0\n") ||
        !cold_file_contains_text(noalias_report_path, "no_alias_cached_loads_elided=") ||
        cold_file_contains_text(noalias_report_path, "no_alias_cached_loads_elided=0\n") ||
        !cold_file_contains_text(noalias_report_path, "egraph_fixed_point_iterations=") ||
        !cold_file_contains_text(noalias_report_path, "cross_block_analysis_ran=1\n")) {
        fprintf(stderr, "[cheng_cold] run-host-smokes: no-alias/egraph report mismatch: %s\n",
                noalias_report_path);
        return 1;
    }
    if (cold_host_smoke_skip_cross_host_runtime("compiler_csg_egraph_active_contract_smoke",
                                                "arm64-apple-darwin",
                                                out_path)) {
        printf("  PASS compiler_csg_egraph_active_contract_smoke compile\n");
        printf("  PASS cold_noalias_egraph_contract_smoke compile\n");
        return 0;
    }
    if (!cold_run_executable_expect(out_path, 0, 0,
                                    " compiler_csg_egraph_active_contract_smoke ok")) {
        fprintf(stderr, "[cheng_cold] run-host-smokes: egraph contract executable mismatch: %s\n", out_path);
        return 1;
    }
    if (!cold_run_executable_noargs_rc(noalias_out_path, 0)) {
        fprintf(stderr, "[cheng_cold] run-host-smokes: no-alias contract executable mismatch: %s\n",
                noalias_out_path);
        return 1;
    }
    printf("  PASS compiler_csg_egraph_active_contract_smoke\n");
    printf("  PASS cold_noalias_egraph_contract_smoke\n");
    return 0;
}

