static int cold_run_host_smoke_std_file_io(int argc, char **argv, const char *root) {
    (void)argc;
    (void)argv;
#if !defined(__APPLE__)
    /* std_file_io_smoke exercises the --link-providers system-cc path.
       On non-Darwin hosts the native host-runtime providers (cheng_free,
       cheng_fclose, cheng_file_handle_*, etc.) are not yet implemented
       as linkable objects — they exist only as inline codegen in the
       linkerless path.  Skip until Linux x86_64 host-runtime providers
       are added. */
    printf("  SKIP std_file_io_smoke reason=linux_host_runtime_providers_not_yet_implemented\n");
    return 0;
#endif
    char out_dir[PATH_MAX];
    char compiler_path[PATH_MAX];
    char source_path[PATH_MAX];
    char out_path[PATH_MAX];
    char report_path[PATH_MAX];
    cold_join_path(out_dir, sizeof(out_dir), root, "artifacts/hostrun/cold_builtin");
    if (!cold_mkdir_p(out_dir)) {
        fprintf(stderr, "[cheng_cold] run-host-smokes: failed to create %s\n", out_dir);
        return 1;
    }
    cold_join_path(compiler_path, sizeof(compiler_path), root, "artifacts/bootstrap/cheng.stage3");
    cold_join_path(source_path, sizeof(source_path), root, "src/tests/std_file_io_smoke.cheng");
    cold_join_path(out_path, sizeof(out_path), out_dir, "std_file_io_smoke");
    cold_format_exact_or_die(
        report_path, sizeof(report_path),
        "file I/O smoke report path too long",
        "%s.report.txt", out_path);
    unlink(out_path);
    unlink(report_path);
    if (!cold_file_exists_nonempty(source_path)) {
        fprintf(stderr, "[cheng_cold] run-host-smokes: missing source %s\n", source_path);
        return 1;
    }
    if (!cold_file_exists_nonempty(compiler_path)) {
        fprintf(stderr, "[cheng_cold] run-host-smokes: missing compiler %s\n", compiler_path);
        return 1;
    }
    char root_arg[PATH_MAX + 16];
    char in_arg[PATH_MAX + 16];
    char out_arg[PATH_MAX + 16];
    char report_arg[PATH_MAX + 32];
    char q_compiler[PATH_MAX * 5 + 8];
    char q_root_arg[PATH_MAX * 5 + 32];
    char q_in_arg[PATH_MAX * 5 + 32];
    char q_out_arg[PATH_MAX * 5 + 32];
    char q_report_arg[PATH_MAX * 5 + 40];
    char cmd[PATH_MAX * 24];
    snprintf(root_arg, sizeof(root_arg), "--root:%s", root);
    snprintf(in_arg, sizeof(in_arg), "--in:%s", source_path);
    snprintf(out_arg, sizeof(out_arg), "--out:%s", out_path);
    snprintf(report_arg, sizeof(report_arg), "--report-out:%s", report_path);
    if (!cold_shell_quote(q_compiler, sizeof(q_compiler), compiler_path) ||
        !cold_shell_quote(q_root_arg, sizeof(q_root_arg), root_arg) ||
        !cold_shell_quote(q_in_arg, sizeof(q_in_arg), in_arg) ||
        !cold_shell_quote(q_out_arg, sizeof(q_out_arg), out_arg) ||
        !cold_shell_quote(q_report_arg, sizeof(q_report_arg), report_arg)) return 1;
    snprintf(cmd, sizeof(cmd),
             "CHENG_NO_BACKEND_DRIVER_HANDOFF=1 CHENG_BACKEND_DRIVER_HANDOFF=0 BACKEND_INCREMENTAL=0 BACKEND_MULTI_MODULE_CACHE=0 CHENG_DISABLE_PRIMARY_OBJECT_CACHE=1 CHENG_PROGRESS=1 CHENG_PROCESS_MAX_RSS_BYTES=1073741824 %s system-link-exec %s %s --emit:exe --target:arm64-apple-darwin %s %s --link-providers",
             q_compiler, q_root_arg, q_in_arg, q_out_arg, q_report_arg);
    if (!cold_run_shell(cmd, "run-host-smokes std_file_io_smoke")) return 1;
    if (!cold_file_exists_nonempty(out_path) ||
        !cold_file_contains_text(report_path, "system_link_exec=1\n") ||
        !cold_file_contains_text(report_path, "real_backend_codegen=1\n") ||
        !cold_file_contains_text(report_path, "unresolved_symbol_count=0\n") ||
        !cold_file_contains_text(report_path, "provider_object_count=") ||
        cold_file_contains_text(report_path, "provider_object_count=0\n")) {
        fprintf(stderr, "[cheng_cold] run-host-smokes: std_file_io report mismatch: %s\n", report_path);
        return 1;
    }
    if (!cold_run_executable_noargs_rc(out_path, 0)) {
        fprintf(stderr, "[cheng_cold] run-host-smokes: std_file_io executable exit mismatch: %s\n", out_path);
        return 1;
    }
    printf("  PASS std_file_io_smoke\n");
    return 0;
}

static int cold_run_host_smoke_function_task_ws_determinism(int argc, char **argv, const char *root) {
    (void)argc;
    char out_dir[PATH_MAX];
    char source_path[PATH_MAX];
    char obj_one[PATH_MAX];
    char obj_four[PATH_MAX];
    char report_one[PATH_MAX];
    char report_four[PATH_MAX];
    cold_join_path(out_dir, sizeof(out_dir), root, "artifacts/hostrun/cold_builtin");
    if (!cold_mkdir_p(out_dir)) {
        fprintf(stderr, "[cheng_cold] run-host-smokes: failed to create %s\n", out_dir);
        return 1;
    }
    cold_join_path(source_path, sizeof(source_path), root, "src/tests/fixtures/function_task_simple.cheng");
    cold_join_path(obj_one, sizeof(obj_one), out_dir, "function_task_ws_jobs1.o");
    cold_join_path(obj_four, sizeof(obj_four), out_dir, "function_task_ws_jobs4.o");
    cold_format_exact_or_die(
        report_one, sizeof(report_one),
        "function-task single-worker report path too long",
        "%s.report.txt", obj_one);
    cold_format_exact_or_die(
        report_four, sizeof(report_four),
        "function-task four-worker report path too long",
        "%s.report.txt", obj_four);
    unlink(obj_one);
    unlink(obj_four);
    unlink(report_one);
    unlink(report_four);
    if (!cold_file_exists_nonempty(source_path)) {
        fprintf(stderr, "[cheng_cold] run-host-smokes: missing source %s\n", source_path);
        return 1;
    }

    char root_arg[PATH_MAX + 16];
    char in_arg[PATH_MAX + 16];
    char out_one_arg[PATH_MAX + 16];
    char out_four_arg[PATH_MAX + 16];
    char report_one_arg[PATH_MAX + 32];
    char report_four_arg[PATH_MAX + 32];
    snprintf(root_arg, sizeof(root_arg), "--root:%s", root);
    snprintf(in_arg, sizeof(in_arg), "--in:%s", source_path);
    snprintf(out_one_arg, sizeof(out_one_arg), "--out:%s", obj_one);
    snprintf(out_four_arg, sizeof(out_four_arg), "--out:%s", obj_four);
    snprintf(report_one_arg, sizeof(report_one_arg), "--report-out:%s", report_one);
    snprintf(report_four_arg, sizeof(report_four_arg), "--report-out:%s", report_four);

    const char *old_jobs = getenv("BACKEND_JOBS");
    char *old_jobs_copy = cold_copy_env_value(old_jobs);
    if (old_jobs && !old_jobs_copy) {
        fprintf(stderr, "[cheng_cold] run-host-smokes: failed to copy BACKEND_JOBS\n");
        return 1;
    }
    int rc = 0;
    char *compile_one_argv[] = {
        argv[0],
        "system-link-exec",
        root_arg,
        in_arg,
        "--emit:obj",
        "--target:arm64-apple-darwin",
        out_one_arg,
        report_one_arg,
    };
    setenv("BACKEND_JOBS", "1", 1);
    rc = cold_cmd_system_link_exec(8, compile_one_argv);
    if (rc != 0) goto done;

    char *compile_four_argv[] = {
        argv[0],
        "system-link-exec",
        root_arg,
        in_arg,
        "--emit:obj",
        "--target:arm64-apple-darwin",
        out_four_arg,
        report_four_arg,
    };
    setenv("BACKEND_JOBS", "4", 1);
    rc = cold_cmd_system_link_exec(8, compile_four_argv);
    if (rc != 0) goto done;

    if (!cold_file_exists_nonempty(obj_one) ||
        !cold_file_exists_nonempty(obj_four) ||
        !cold_file_contains_text(report_one, "function_task_job_count=1\n") ||
        !cold_file_contains_text(report_one, "function_task_schedule=none\n") ||
        !cold_file_contains_text(report_one, "lowering_parallel_status=none\n") ||
        !cold_file_contains_text(report_one, "lowering_parallel_job_count=0\n") ||
        !cold_file_contains_text(report_one, "real_backend_codegen=1\n") ||
        !cold_file_contains_text(report_one, "unresolved_symbol_count=0\n") ||
        !cold_file_contains_text(report_four, "function_task_job_count=4\n") ||
        !cold_file_contains_text(report_four, "function_task_schedule=none\n") ||
        !cold_file_contains_text(report_four, "lowering_parallel_status=none\n") ||
        !cold_file_contains_text(report_four, "lowering_parallel_job_count=0\n") ||
        !cold_file_contains_text(report_four, "lowering_parallel_completed_workers=0\n") ||
        !cold_file_contains_text(report_four, "real_backend_codegen=1\n") ||
        !cold_file_contains_text(report_four, "unresolved_symbol_count=0\n")) {
        fprintf(stderr, "[cheng_cold] run-host-smokes: function task ws report mismatch\n");
        rc = 1;
        goto done;
    }
    if (!cold_files_equal(obj_one, obj_four)) {
        fprintf(stderr, "[cheng_cold] run-host-smokes: function task ws output drift\n");
        rc = 1;
        goto done;
    }
    printf("  PASS function_task_ws_determinism_smoke\n");

done:
    cold_restore_env_value("BACKEND_JOBS", old_jobs_copy);
    if (old_jobs_copy) free(old_jobs_copy);
    return rc;
}

